CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,name text NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('CUSTOMER','STAFF','ADMIN')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),csrf text NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sku varchar(40) UNIQUE NOT NULL,name varchar(120) NOT NULL,description text NOT NULL,category varchar(50) NOT NULL,price integer NOT NULL CHECK(price>0 AND price<=100000000),on_hand integer NOT NULL CHECK(on_hand>=0),reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=on_hand),active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_catalog ON products(active,category,created_at,id);
CREATE TABLE coupons(code varchar(24) PRIMARY KEY,percent integer NOT NULL CHECK(percent BETWEEN 1 AND 50),minimum integer NOT NULL DEFAULT 0 CHECK(minimum>=0),max_uses integer NOT NULL CHECK(max_uses>0),used integer NOT NULL DEFAULT 0 CHECK(used>=0 AND used<=max_uses),active boolean NOT NULL DEFAULT true,expires_at timestamptz NOT NULL);
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PAID','PACKED','SHIPPED','DELIVERED','CANCELLED','EXPIRED','RETURNED')),subtotal integer NOT NULL CHECK(subtotal>0),discount integer NOT NULL CHECK(discount>=0 AND discount<=subtotal),shipping integer NOT NULL CHECK(shipping>=0),total integer NOT NULL CHECK(total=subtotal-discount+shipping),currency text NOT NULL DEFAULT 'BDT' CHECK(currency='BDT'),coupon_code varchar(24) REFERENCES coupons(code),address jsonb NOT NULL,expires_at timestamptz NOT NULL,tracking text,delivered_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_user ON orders(user_id,created_at DESC,id);
CREATE INDEX orders_expiry ON orders(expires_at) WHERE status='PENDING';
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),product_id uuid NOT NULL REFERENCES products(id),sku text NOT NULL,name text NOT NULL,quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 10),price integer NOT NULL CHECK(price>0),UNIQUE(order_id,product_id));
CREATE TABLE idempotency(user_id uuid NOT NULL REFERENCES users(id),key text NOT NULL,fingerprint text NOT NULL,order_id uuid NOT NULL REFERENCES orders(id),PRIMARY KEY(user_id,key));
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL UNIQUE REFERENCES orders(id),provider text NOT NULL DEFAULT 'sandbox' CHECK(provider IN ('sandbox','stripe','bkash')),state text NOT NULL DEFAULT 'CREATED' CHECK(state IN ('CREATED','INITIATING','UNKNOWN','READY','SUCCEEDED','FAILED')),amount integer NOT NULL CHECK(amount>0),currency text NOT NULL DEFAULT 'BDT',invoice text NOT NULL UNIQUE,remote_id text,checkout_url text,settlement_reference text,last_checked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,remote_id));
CREATE TABLE payment_events(provider text NOT NULL,event_id text NOT NULL,fingerprint text NOT NULL,payment_id uuid NOT NULL REFERENCES payments(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(provider,event_id));
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL UNIQUE REFERENCES orders(id),payment_id uuid NOT NULL REFERENCES payments(id),amount integer NOT NULL CHECK(amount>0),reason text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','COMPLETED')),reference text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE returns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL UNIQUE REFERENCES orders(id),reason text NOT NULL,status text NOT NULL DEFAULT 'REQUESTED' CHECK(status IN ('REQUESTED','APPROVED','REJECTED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory_ledger(id bigserial PRIMARY KEY,product_id uuid NOT NULL REFERENCES products(id),order_id uuid REFERENCES orders(id),actor_id uuid REFERENCES users(id),kind text NOT NULL,on_hand_delta integer NOT NULL,reserved_delta integer NOT NULL,reference text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ledger_product ON inventory_ledger(product_id,id DESC);
CREATE TABLE stock_requests(actor_id uuid NOT NULL REFERENCES users(id),key text NOT NULL,fingerprint text NOT NULL,product_id uuid NOT NULL REFERENCES products(id),PRIMARY KEY(actor_id,key));
CREATE TABLE audit(id bigserial PRIMARY KEY,order_id uuid REFERENCES orders(id),actor_id uuid REFERENCES users(id),action text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_order ON audit(order_id,id);
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL,order_id uuid NOT NULL REFERENCES orders(id),payload jsonb NOT NULL DEFAULT '{}',published_at timestamptz,processed_at timestamptz,attempts integer NOT NULL DEFAULT 0,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending ON outbox(created_at) WHERE processed_at IS NULL;
CREATE TABLE notifications(id uuid PRIMARY KEY REFERENCES outbox(id),user_id uuid NOT NULL REFERENCES users(id),order_id uuid NOT NULL REFERENCES orders(id),message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE worker_heartbeat(name text PRIMARY KEY,seen_at timestamptz NOT NULL);
